messages.content:
{
  "status": "awaiting_task_selection",
  "interim_tasks": [
    {
      "id": "task-mapping",
      "title": "Finalize data migration mapping and validation plan",
      "description": "Lock in source-to-target data mappings, define validation checks, and establish acceptance criteria for migration.",
      "next_steps": [
        "Collect current data schemas and transformation rules",
        "Define validation checks (row counts, integrity checks, sample data verification)",
        "Assign data owners and sign-off criteria"
      ]
    },
    {
      "id": "task-report-template",
      "title": "Prepare post-benchmark reporting templates",
      "description": "Create standardized reports to capture benchmark results, SLA metrics, and vendor capacity insights.",
      "next_steps": [
        "List key metrics to report (throughput, latency, success rate, SLA conformance)",
        "Draft report layout and executive summary section",
        "Identify data sources and auto-generation steps"
      ]
    },
    {
      "id": "task-health-checks",
      "title": "Review health-check endpoints for the premium compliance API",
      "description": "Verify that health-check endpoints return green status and define failure thresholds for alerts.",
      "next_steps": [
        "Compile the list of required endpoints",
        "Run test requests and capture response times and statuses",
        "Document remediation steps for any non-green responses"
      ]
    },
    {
      "id": "task-rollback",
      "title": "Confirm rollback plan and recovery time objectives",
      "description": "Ensure there is a tested rollback procedure with defined RTO and RPO for the migration.",
      "next_steps": [
        "Draft rollback steps and decision points",
        "Define rollback timing and resource requirements",
        "Schedule a dry-run or tabletop exercise if feasible"
      ]
    }
  ],
  "reminder_options": [
    {
      "id": "remind-approval",
      "label": "Set a reminder to check SRE approval status",
      "time_hint": "Specify when you want the reminder (e.g., 1 hour, 4 hours, daily)."
    }
  ],
  "prompt": "Please tell me which tasks you'd like me to start first, and if you want a reminder set, provide the preferred time and frequency (e.g., 1 hour before approval, daily at 09:00)."
}

